<?php use App\Core\Helpers as H;?><h1>Promotions</h1><h2>Promo Pricing</h2><p>Placement and duration are fixed. New prices apply only to future purchases.</p><div class="promo-pricing"><?php foreach($packages as $p):?><form method="post" class="card"><input type="hidden" name="_csrf" value="<?=H::csrf()?>"><input type="hidden" name="action" value="update_price"><input type="hidden" name="id" value="<?=$p['id']?>"><strong><?=H::e(ucwords(str_replace('_',' ',$p['placement'])))?> — <?=$p['duration_value'].' '.$p['duration_unit'].($p['duration_value']>1?'s':'')?></strong><label style="display:block;margin-top:10px;">Price $ <input type="number" name="price" min="0.01" step="0.01" value="<?=number_format($p['price_cents']/100,2,'.','')?>"></label><button>Save</button></form><?php endforeach;?></div>
<h2>Campaigns</h2><div class="promo-table"><table><tr><th>Seller / target</th><th>Placement</th><th>Snapshot</th><th>Payment / status</th><th>Schedule</th><th>Stats</th><th>Actions</th></tr><?php foreach($campaigns as $a):?><tr><td><?=H::e($a['display_name'])?><br><?=H::e($a['target_type']==='shop'?'Shop':($a['product_title']??'Unavailable product'))?></td><td><?=H::e($a['placement'])?><?=!empty($a['category_name'])?'<br>'.H::e($a['category_name']):''?></td><td><?=$a['duration_value'].' '.$a['duration_unit']?><br><?=H::money($a['price_cents']/100)?></td><td><?=H::e($a['payment_status'])?><br><?=H::e($a['status'])?></td><td><?php if($a['placement']==='weekly_email'):?>Appearances: <?=(int)$a['email_appearances_used']?> / <?=(int)$a['email_total_appearances']?><?php else:?><?=H::e($a['starts_at']??'—')?><br><?=H::e($a['ends_at']??'—')?><?php endif;?></td><td><?php if($a['placement']==='weekly_email'):?>Recipient sends: <?=(int)$a['email_recipient_sends']?><br>Clicks: <?=(int)$a['clicks']?><?php else:?>Impressions: <?=(int)$a['impressions']?><br>Clicks: <?=(int)$a['clicks']?><?php endif;?></td><td><?php $actions=$a['status']==='active'?['pause','remove']:($a['status']==='paused'?['resume','remove']:(!empty($a['emergency_removable'])?['remove']:[]));foreach($actions as $action):?><form method="post"><input type="hidden" name="_csrf" value="<?=H::csrf()?>"><input type="hidden" name="id" value="<?=$a['id']?>"><button name="action" value="<?=$action?>"><?=ucfirst($action)?></button></form><?php endforeach;?></td></tr><?php endforeach;?></table></div>
